window.MG_LAZY_DATA["data/lazy/owner-courses/a080-590d475de4f723a2.json"]={sha256:"590d475de4f723a20472ad3f0d906cd3a9397d288f07a433ac00961435438975",value:{"id":"a080","title":"單光子雪崩二極體陣列","titleEn":"Single-photon avalanche-diode arrays","category":"semiconductor","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","curriculumVersion":8,"depth":4,"stepCount":24,"estimatedMinutes":550,"languageCoverage":["zh-TW","en"],"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof","v8-c-ham-place","v8-c-ham-history","v3-media-80679a241086"],"simulationOnly":true,"summary":"從Geiger 觸發、後脈衝到熱點像素：以 12 項工程決策、24 個模型與診斷工作包建立證據。","summaryEn":"From Geiger triggering and Afterpulsing to Hot pixels: build evidence through twelve engineering decisions and twenty-four modeling/diagnostic work packages.","scope":"公開原理的教學拆解：12 個技術主題各有模型／分析及故障／驗證兩步，共四階段 24 步。不是 24 道實際製造配方，也不是任何廠商量產流程。數值由學員自訂並標示為假設；涉及材料加工、高壓、雷射或化學品的活動僅做圖上與資料分析，不由網頁授權實機操作。","scopeEn":"A public-principles educational decomposition: twelve technical topics each have a model/analysis step and a diagnosis/verification step, organized as four stages and twenty-four work packages. These are not twenty-four fabrication recipes or a manufacturer flow. Learner-selected numbers are hypothetical; materials processing, high voltage, lasers and chemicals are studied through diagrams/data, not authorized physical operation.","diagram":{"type":"wafer","labels":["Geiger 觸發","暗計數","死時間","直接飛行時間"],"labelsEn":["Geiger triggering","Dark counts","Dead time","Direct time of flight"],"original":true,"notToScale":true},"stages":[{"id":"a080-stage01","order":1,"title":"Geiger 觸發 → 偵測機率","titleEn":"Geiger triggering to Photon-detection probability","description":"把「Geiger 觸發」「淬熄復位」「偵測機率」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Geiger triggering, Quench and reset, Photon-detection probability.","steps":[{"id":"a080-v8-01","order":1,"sequence":1,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":[],"title":"Geiger 觸發：建立模型","titleEn":"Geiger triggering: construct and analyze","objective":"用可檢查的成果說明「單像素飽和脈衝不直接量出同時光子數」。","objectiveEn":"Demonstrate the following with inspectable work: A saturated pixel pulse does not directly count simultaneous photons.","instruction":"畫超額偏壓與雪崩觸發後的脈衝，分離光子數和脈衝幅度。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Draw excess bias and triggered pulses and separate photon count from pulse height. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"單像素飽和脈衝不直接量出同時光子數；多像素數可擴展陣列動態範圍。","observationEn":"A saturated pixel pulse does not directly count simultaneous photons; More microcells can extend array dynamic range.","failure":"若採用「用單一雪崩脈衝高度精確判斷入射光子數」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Inferring exact photon number from one avalanche height\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「Geiger 觸發」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：單像素飽和脈衝不直接量出同時光子數。","checkEn":"Submit the Geiger triggering diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: A saturated pixel pulse does not directly count simultaneous photons.","knowledge":[{"id":"a080-v8-01-k1","title":"Geiger 觸發／物理與模型","titleEn":"Geiger triggering / Physics and model","text":"機制：單像素飽和脈衝不直接量出同時光子數。","textEn":"Mechanism: A saturated pixel pulse does not directly count simultaneous photons."},{"id":"a080-v8-01-k2","title":"Geiger 觸發／驗證與限制","titleEn":"Geiger triggering / Verification and limits","text":"模型邊界：不可由目前成果直接推出「用單一雪崩脈衝高度精確判斷入射光子數」。","textEn":"Model boundary: the current result does not establish the following claim: Inferring exact photon number from one avalanche height."}],"quiz":{"question":"關於「Geiger 觸發」，哪項推論有物理依據？","questionEn":"For Geiger triggering, which inference has a physical basis?","options":["單像素飽和脈衝不直接量出同時光子數","用單一雪崩脈衝高度精確判斷入射光子數","只加大偏壓就能不間斷偵測"],"optionsEn":["A saturated pixel pulse does not directly count simultaneous photons","Inferring exact photon number from one avalanche height","Assuming higher bias enables uninterrupted detection"],"answer":0,"explanation":"單像素飽和脈衝不直接量出同時光子數；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"A saturated pixel pulse does not directly count simultaneous photons. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-02","order":2,"sequence":2,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-01"],"title":"Geiger 觸發：故障判讀與驗證","titleEn":"Geiger triggering: diagnose and verify","objective":"以新增對照檢查「用單一雪崩脈衝高度精確判斷入射光子數」這項錯誤主張。","objectiveEn":"Test the faulty claim: Inferring exact photon number from one avalanche height.","instruction":"接續前一步「Geiger 觸發」成果，先指出錯誤主張「用單一雪崩脈衝高度精確判斷入射光子數」漏掉哪個條件。新增診斷原理：多像素數可擴展陣列動態範圍。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Geiger triggering artifact. Identify the missing condition in the faulty claim \"Inferring exact photon number from one avalanche height\". Introduce this diagnostic principle: More microcells can extend array dynamic range. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"單像素飽和脈衝不直接量出同時光子數；多像素數可擴展陣列動態範圍。","observationEn":"A saturated pixel pulse does not directly count simultaneous photons; More microcells can extend array dynamic range.","failure":"若採用「用單一雪崩脈衝高度精確判斷入射光子數」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Inferring exact photon number from one avalanche height\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「Geiger 觸發」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「多像素數可擴展陣列動態範圍」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Geiger triggering, its observable and one remaining uncertainty. Explain how \"More microcells can extend array dynamic range\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-02-k1","title":"Geiger 觸發／物理與模型","titleEn":"Geiger triggering / Physics and model","text":"診斷機制：多像素數可擴展陣列動態範圍。","textEn":"Diagnostic mechanism: More microcells can extend array dynamic range."},{"id":"a080-v8-02-k2","title":"Geiger 觸發／驗證與限制","titleEn":"Geiger triggering / Verification and limits","text":"可證偽性：「用單一雪崩脈衝高度精確判斷入射光子數」與「單像素飽和脈衝不直接量出同時光子數」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Inferring exact photon number from one avalanche height\" is not equivalent to \"A saturated pixel pulse does not directly count simultaneous photons\"; the control must expose their difference."}],"quiz":{"question":"檢查「Geiger 觸發」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Geiger triggering?","options":["只加大偏壓就能不間斷偵測","多像素數可擴展陣列動態範圍","用單一雪崩脈衝高度精確判斷入射光子數"],"optionsEn":["Assuming higher bias enables uninterrupted detection","More microcells can extend array dynamic range","Inferring exact photon number from one avalanche height"],"answer":1,"explanation":"多像素數可擴展陣列動態範圍；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"More microcells can extend array dynamic range. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-03","order":3,"sequence":3,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-02"],"title":"淬熄復位：建立模型","titleEn":"Quench and reset: construct and analyze","objective":"用可檢查的成果說明「雪崩需要淬熄後才能可靠重新偵測」。","objectiveEn":"Demonstrate the following with inspectable work: Avalanche must be quenched before reliable redetection.","instruction":"畫觸發、降至崩潰以下與恢復偏壓三段時間圖。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Draw trigger, below-breakdown quench and bias-recovery timing. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"雪崩需要淬熄後才能可靠重新偵測；復位中的像素可能暫時低靈敏。","observationEn":"Avalanche must be quenched before reliable redetection; Recovering pixels may have reduced sensitivity.","failure":"若採用「只加大偏壓就能不間斷偵測」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming higher bias enables uninterrupted detection\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「淬熄復位」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：雪崩需要淬熄後才能可靠重新偵測。","checkEn":"Submit the Quench and reset diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Avalanche must be quenched before reliable redetection.","knowledge":[{"id":"a080-v8-03-k1","title":"淬熄復位／物理與模型","titleEn":"Quench and reset / Physics and model","text":"機制：雪崩需要淬熄後才能可靠重新偵測。","textEn":"Mechanism: Avalanche must be quenched before reliable redetection."},{"id":"a080-v8-03-k2","title":"淬熄復位／驗證與限制","titleEn":"Quench and reset / Verification and limits","text":"模型邊界：不可由目前成果直接推出「只加大偏壓就能不間斷偵測」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming higher bias enables uninterrupted detection."}],"quiz":{"question":"關於「淬熄復位」，哪項推論有物理依據？","questionEn":"For Quench and reset, which inference has a physical basis?","options":["只加大偏壓就能不間斷偵測","將不同定義 PDE 數字直接排名","雪崩需要淬熄後才能可靠重新偵測"],"optionsEn":["Assuming higher bias enables uninterrupted detection","Ranking PDE values with different definitions","Avalanche must be quenched before reliable redetection"],"answer":2,"explanation":"雪崩需要淬熄後才能可靠重新偵測；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Avalanche must be quenched before reliable redetection. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-04","order":4,"sequence":4,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-03"],"title":"淬熄復位：故障判讀與驗證","titleEn":"Quench and reset: diagnose and verify","objective":"以新增對照檢查「只加大偏壓就能不間斷偵測」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming higher bias enables uninterrupted detection.","instruction":"接續前一步「淬熄復位」成果，先指出錯誤主張「只加大偏壓就能不間斷偵測」漏掉哪個條件。新增診斷原理：復位中的像素可能暫時低靈敏。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Quench and reset artifact. Identify the missing condition in the faulty claim \"Assuming higher bias enables uninterrupted detection\". Introduce this diagnostic principle: Recovering pixels may have reduced sensitivity. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"雪崩需要淬熄後才能可靠重新偵測；復位中的像素可能暫時低靈敏。","observationEn":"Avalanche must be quenched before reliable redetection; Recovering pixels may have reduced sensitivity.","failure":"若採用「只加大偏壓就能不間斷偵測」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming higher bias enables uninterrupted detection\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「淬熄復位」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「復位中的像素可能暫時低靈敏」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Quench and reset, its observable and one remaining uncertainty. Explain how \"Recovering pixels may have reduced sensitivity\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-04-k1","title":"淬熄復位／物理與模型","titleEn":"Quench and reset / Physics and model","text":"診斷機制：復位中的像素可能暫時低靈敏。","textEn":"Diagnostic mechanism: Recovering pixels may have reduced sensitivity."},{"id":"a080-v8-04-k2","title":"淬熄復位／驗證與限制","titleEn":"Quench and reset / Verification and limits","text":"可證偽性：「只加大偏壓就能不間斷偵測」與「雪崩需要淬熄後才能可靠重新偵測」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming higher bias enables uninterrupted detection\" is not equivalent to \"Avalanche must be quenched before reliable redetection\"; the control must expose their difference."}],"quiz":{"question":"檢查「淬熄復位」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Quench and reset?","options":["復位中的像素可能暫時低靈敏","只加大偏壓就能不間斷偵測","將不同定義 PDE 數字直接排名"],"optionsEn":["Recovering pixels may have reduced sensitivity","Assuming higher bias enables uninterrupted detection","Ranking PDE values with different definitions"],"answer":0,"explanation":"復位中的像素可能暫時低靈敏；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Recovering pixels may have reduced sensitivity. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-05","order":5,"sequence":5,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-04"],"title":"偵測機率：建立模型","titleEn":"Photon-detection probability: construct and analyze","objective":"用可檢查的成果說明「偵測效率定義必須說明是否包含填充因子」。","objectiveEn":"Demonstrate the following with inspectable work: Efficiency definitions must state whether fill factor is included.","instruction":"分拆吸收、收集及觸發機率並區分像素 PDE 與陣列填充因子。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Separate absorption, collection and trigger probabilities from array fill factor. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"偵測效率定義必須說明是否包含填充因子；超額偏壓也影響暗計數和串擾。","observationEn":"Efficiency definitions must state whether fill factor is included; Excess bias also affects dark counts and crosstalk.","failure":"若採用「將不同定義 PDE 數字直接排名」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Ranking PDE values with different definitions\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「偵測機率」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：偵測效率定義必須說明是否包含填充因子。","checkEn":"Submit the Photon-detection probability diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Efficiency definitions must state whether fill factor is included.","knowledge":[{"id":"a080-v8-05-k1","title":"偵測機率／物理與模型","titleEn":"Photon-detection probability / Physics and model","text":"機制：偵測效率定義必須說明是否包含填充因子。","textEn":"Mechanism: Efficiency definitions must state whether fill factor is included."},{"id":"a080-v8-05-k2","title":"偵測機率／驗證與限制","titleEn":"Photon-detection probability / Verification and limits","text":"模型邊界：不可由目前成果直接推出「將不同定義 PDE 數字直接排名」。","textEn":"Model boundary: the current result does not establish the following claim: Ranking PDE values with different definitions."}],"quiz":{"question":"關於「偵測機率」，哪項推論有物理依據？","questionEn":"For Photon-detection probability, which inference has a physical basis?","options":["以暗電流單位報告暗計數率","偵測效率定義必須說明是否包含填充因子","將不同定義 PDE 數字直接排名"],"optionsEn":["Reporting dark count in current units","Efficiency definitions must state whether fill factor is included","Ranking PDE values with different definitions"],"answer":1,"explanation":"偵測效率定義必須說明是否包含填充因子；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Efficiency definitions must state whether fill factor is included. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-06","order":6,"sequence":6,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-05"],"title":"偵測機率：故障判讀與驗證","titleEn":"Photon-detection probability: diagnose and verify","objective":"以新增對照檢查「將不同定義 PDE 數字直接排名」這項錯誤主張。","objectiveEn":"Test the faulty claim: Ranking PDE values with different definitions.","instruction":"接續前一步「偵測機率」成果，先指出錯誤主張「將不同定義 PDE 數字直接排名」漏掉哪個條件。新增診斷原理：超額偏壓也影響暗計數和串擾。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Photon-detection probability artifact. Identify the missing condition in the faulty claim \"Ranking PDE values with different definitions\". Introduce this diagnostic principle: Excess bias also affects dark counts and crosstalk. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"偵測效率定義必須說明是否包含填充因子；超額偏壓也影響暗計數和串擾。","observationEn":"Efficiency definitions must state whether fill factor is included; Excess bias also affects dark counts and crosstalk.","failure":"若採用「將不同定義 PDE 數字直接排名」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Ranking PDE values with different definitions\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「偵測機率」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「超額偏壓也影響暗計數和串擾」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Photon-detection probability, its observable and one remaining uncertainty. Explain how \"Excess bias also affects dark counts and crosstalk\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-06-k1","title":"偵測機率／物理與模型","titleEn":"Photon-detection probability / Physics and model","text":"診斷機制：超額偏壓也影響暗計數和串擾。","textEn":"Diagnostic mechanism: Excess bias also affects dark counts and crosstalk."},{"id":"a080-v8-06-k2","title":"偵測機率／驗證與限制","titleEn":"Photon-detection probability / Verification and limits","text":"可證偽性：「將不同定義 PDE 數字直接排名」與「偵測效率定義必須說明是否包含填充因子」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Ranking PDE values with different definitions\" is not equivalent to \"Efficiency definitions must state whether fill factor is included\"; the control must expose their difference."}],"quiz":{"question":"檢查「偵測機率」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Photon-detection probability?","options":["將不同定義 PDE 數字直接排名","以暗電流單位報告暗計數率","超額偏壓也影響暗計數和串擾"],"optionsEn":["Ranking PDE values with different definitions","Reporting dark count in current units","Excess bias also affects dark counts and crosstalk"],"answer":2,"explanation":"超額偏壓也影響暗計數和串擾；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Excess bias also affects dark counts and crosstalk. The competing claim omits a necessary condition or mechanism."}}]},{"id":"a080-stage02","order":2,"title":"暗計數 → 光學串擾","titleEn":"Dark counts to Optical crosstalk","description":"把「暗計數」「後脈衝」「光學串擾」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Dark counts, Afterpulsing, Optical crosstalk.","steps":[{"id":"a080-v8-07","order":1,"sequence":7,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-06"],"title":"暗計數：建立模型","titleEn":"Dark counts: construct and analyze","objective":"用可檢查的成果說明「暗計數是事件率而非連續暗電流」。","objectiveEn":"Demonstrate the following with inspectable work: Dark count is an event rate, not continuous dark current.","instruction":"在遮光下建立每像素計數率地圖和溫度對照。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Map per-pixel dark rates under shielding with temperature controls. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"暗計數是事件率而非連續暗電流；熱像素尾端不能只用全片平均表示。","observationEn":"Dark count is an event rate, not continuous dark current; Hot-pixel tails need more than a wafer mean.","failure":"若採用「以暗電流單位報告暗計數率」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Reporting dark count in current units\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「暗計數」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：暗計數是事件率而非連續暗電流。","checkEn":"Submit the Dark counts diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Dark count is an event rate, not continuous dark current.","knowledge":[{"id":"a080-v8-07-k1","title":"暗計數／物理與模型","titleEn":"Dark counts / Physics and model","text":"機制：暗計數是事件率而非連續暗電流。","textEn":"Mechanism: Dark count is an event rate, not continuous dark current."},{"id":"a080-v8-07-k2","title":"暗計數／驗證與限制","titleEn":"Dark counts / Verification and limits","text":"模型邊界：不可由目前成果直接推出「以暗電流單位報告暗計數率」。","textEn":"Model boundary: the current result does not establish the following claim: Reporting dark count in current units."}],"quiz":{"question":"關於「暗計數」，哪項推論有物理依據？","questionEn":"For Dark counts, which inference has a physical basis?","options":["暗計數是事件率而非連續暗電流","以暗電流單位報告暗計數率","將所有延遲事件當成獨立背景光"],"optionsEn":["Dark count is an event rate, not continuous dark current","Reporting dark count in current units","Treating all delayed events as independent background photons"],"answer":0,"explanation":"暗計數是事件率而非連續暗電流；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Dark count is an event rate, not continuous dark current. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-08","order":2,"sequence":8,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-07"],"title":"暗計數：故障判讀與驗證","titleEn":"Dark counts: diagnose and verify","objective":"以新增對照檢查「以暗電流單位報告暗計數率」這項錯誤主張。","objectiveEn":"Test the faulty claim: Reporting dark count in current units.","instruction":"接續前一步「暗計數」成果，先指出錯誤主張「以暗電流單位報告暗計數率」漏掉哪個條件。新增診斷原理：熱像素尾端不能只用全片平均表示。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Dark counts artifact. Identify the missing condition in the faulty claim \"Reporting dark count in current units\". Introduce this diagnostic principle: Hot-pixel tails need more than a wafer mean. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"暗計數是事件率而非連續暗電流；熱像素尾端不能只用全片平均表示。","observationEn":"Dark count is an event rate, not continuous dark current; Hot-pixel tails need more than a wafer mean.","failure":"若採用「以暗電流單位報告暗計數率」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Reporting dark count in current units\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「暗計數」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「熱像素尾端不能只用全片平均表示」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Dark counts, its observable and one remaining uncertainty. Explain how \"Hot-pixel tails need more than a wafer mean\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-08-k1","title":"暗計數／物理與模型","titleEn":"Dark counts / Physics and model","text":"診斷機制：熱像素尾端不能只用全片平均表示。","textEn":"Diagnostic mechanism: Hot-pixel tails need more than a wafer mean."},{"id":"a080-v8-08-k2","title":"暗計數／驗證與限制","titleEn":"Dark counts / Verification and limits","text":"可證偽性：「以暗電流單位報告暗計數率」與「暗計數是事件率而非連續暗電流」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Reporting dark count in current units\" is not equivalent to \"Dark count is an event rate, not continuous dark current\"; the control must expose their difference."}],"quiz":{"question":"檢查「暗計數」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Dark counts?","options":["將所有延遲事件當成獨立背景光","熱像素尾端不能只用全片平均表示","以暗電流單位報告暗計數率"],"optionsEn":["Treating all delayed events as independent background photons","Hot-pixel tails need more than a wafer mean","Reporting dark count in current units"],"answer":1,"explanation":"熱像素尾端不能只用全片平均表示；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Hot-pixel tails need more than a wafer mean. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-09","order":3,"sequence":9,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-08"],"title":"後脈衝：建立模型","titleEn":"Afterpulsing: construct and analyze","objective":"用可檢查的成果說明「捕捉載子釋放可形成與前次事件相關的計數」。","objectiveEn":"Demonstrate the following with inspectable work: Released trapped carriers can produce correlated events.","instruction":"畫觸發後延遲事件直方圖，改變保持時間並比對背景。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Histogram delayed events and compare holdoff settings with background. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"捕捉載子釋放可形成與前次事件相關的計數；較長保持時間會降低最大計數率。","observationEn":"Released trapped carriers can produce correlated events; Longer holdoff reduces maximum count rate.","failure":"若採用「將所有延遲事件當成獨立背景光」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Treating all delayed events as independent background photons\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「後脈衝」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：捕捉載子釋放可形成與前次事件相關的計數。","checkEn":"Submit the Afterpulsing diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Released trapped carriers can produce correlated events.","knowledge":[{"id":"a080-v8-09-k1","title":"後脈衝／物理與模型","titleEn":"Afterpulsing / Physics and model","text":"機制：捕捉載子釋放可形成與前次事件相關的計數。","textEn":"Mechanism: Released trapped carriers can produce correlated events."},{"id":"a080-v8-09-k2","title":"後脈衝／驗證與限制","titleEn":"Afterpulsing / Verification and limits","text":"模型邊界：不可由目前成果直接推出「將所有延遲事件當成獨立背景光」。","textEn":"Model boundary: the current result does not establish the following claim: Treating all delayed events as independent background photons."}],"quiz":{"question":"關於「後脈衝」，哪項推論有物理依據？","questionEn":"For Afterpulsing, which inference has a physical basis?","options":["將所有延遲事件當成獨立背景光","同時多像素事件必然都是多個外來光子","捕捉載子釋放可形成與前次事件相關的計數"],"optionsEn":["Treating all delayed events as independent background photons","Assuming coincidences always mean multiple incident photons","Released trapped carriers can produce correlated events"],"answer":2,"explanation":"捕捉載子釋放可形成與前次事件相關的計數；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Released trapped carriers can produce correlated events. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-10","order":4,"sequence":10,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-09"],"title":"後脈衝：故障判讀與驗證","titleEn":"Afterpulsing: diagnose and verify","objective":"以新增對照檢查「將所有延遲事件當成獨立背景光」這項錯誤主張。","objectiveEn":"Test the faulty claim: Treating all delayed events as independent background photons.","instruction":"接續前一步「後脈衝」成果，先指出錯誤主張「將所有延遲事件當成獨立背景光」漏掉哪個條件。新增診斷原理：較長保持時間會降低最大計數率。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Afterpulsing artifact. Identify the missing condition in the faulty claim \"Treating all delayed events as independent background photons\". Introduce this diagnostic principle: Longer holdoff reduces maximum count rate. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"捕捉載子釋放可形成與前次事件相關的計數；較長保持時間會降低最大計數率。","observationEn":"Released trapped carriers can produce correlated events; Longer holdoff reduces maximum count rate.","failure":"若採用「將所有延遲事件當成獨立背景光」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Treating all delayed events as independent background photons\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「後脈衝」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「較長保持時間會降低最大計數率」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Afterpulsing, its observable and one remaining uncertainty. Explain how \"Longer holdoff reduces maximum count rate\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-10-k1","title":"後脈衝／物理與模型","titleEn":"Afterpulsing / Physics and model","text":"診斷機制：較長保持時間會降低最大計數率。","textEn":"Diagnostic mechanism: Longer holdoff reduces maximum count rate."},{"id":"a080-v8-10-k2","title":"後脈衝／驗證與限制","titleEn":"Afterpulsing / Verification and limits","text":"可證偽性：「將所有延遲事件當成獨立背景光」與「捕捉載子釋放可形成與前次事件相關的計數」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Treating all delayed events as independent background photons\" is not equivalent to \"Released trapped carriers can produce correlated events\"; the control must expose their difference."}],"quiz":{"question":"檢查「後脈衝」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Afterpulsing?","options":["較長保持時間會降低最大計數率","將所有延遲事件當成獨立背景光","同時多像素事件必然都是多個外來光子"],"optionsEn":["Longer holdoff reduces maximum count rate","Treating all delayed events as independent background photons","Assuming coincidences always mean multiple incident photons"],"answer":0,"explanation":"較長保持時間會降低最大計數率；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Longer holdoff reduces maximum count rate. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-11","order":5,"sequence":11,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-10"],"title":"光學串擾：建立模型","titleEn":"Optical crosstalk: construct and analyze","objective":"用可檢查的成果說明「雪崩產生的光可能觸發鄰近像素」。","objectiveEn":"Demonstrate the following with inspectable work: Avalanche-generated light can trigger neighbors.","instruction":"畫鄰像素同步事件矩陣，加入遮光及距離對照。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Build neighboring coincidence matrices with shielding/distance controls. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"雪崩產生的光可能觸發鄰近像素；電性串擾也能造成相關事件。","observationEn":"Avalanche-generated light can trigger neighbors; Electrical crosstalk can also correlate events.","failure":"若採用「同時多像素事件必然都是多個外來光子」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming coincidences always mean multiple incident photons\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「光學串擾」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：雪崩產生的光可能觸發鄰近像素。","checkEn":"Submit the Optical crosstalk diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Avalanche-generated light can trigger neighbors.","knowledge":[{"id":"a080-v8-11-k1","title":"光學串擾／物理與模型","titleEn":"Optical crosstalk / Physics and model","text":"機制：雪崩產生的光可能觸發鄰近像素。","textEn":"Mechanism: Avalanche-generated light can trigger neighbors."},{"id":"a080-v8-11-k2","title":"光學串擾／驗證與限制","titleEn":"Optical crosstalk / Verification and limits","text":"模型邊界：不可由目前成果直接推出「同時多像素事件必然都是多個外來光子」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming coincidences always mean multiple incident photons."}],"quiz":{"question":"關於「光學串擾」，哪項推論有物理依據？","questionEn":"For Optical crosstalk, which inference has a physical basis?","options":["將低光強線性外推到任意高光強","雪崩產生的光可能觸發鄰近像素","同時多像素事件必然都是多個外來光子"],"optionsEn":["Extending low-flux linearity to arbitrary flux","Avalanche-generated light can trigger neighbors","Assuming coincidences always mean multiple incident photons"],"answer":1,"explanation":"雪崩產生的光可能觸發鄰近像素；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Avalanche-generated light can trigger neighbors. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-12","order":6,"sequence":12,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-11"],"title":"光學串擾：故障判讀與驗證","titleEn":"Optical crosstalk: diagnose and verify","objective":"以新增對照檢查「同時多像素事件必然都是多個外來光子」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming coincidences always mean multiple incident photons.","instruction":"接續前一步「光學串擾」成果，先指出錯誤主張「同時多像素事件必然都是多個外來光子」漏掉哪個條件。新增診斷原理：電性串擾也能造成相關事件。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Optical crosstalk artifact. Identify the missing condition in the faulty claim \"Assuming coincidences always mean multiple incident photons\". Introduce this diagnostic principle: Electrical crosstalk can also correlate events. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"雪崩產生的光可能觸發鄰近像素；電性串擾也能造成相關事件。","observationEn":"Avalanche-generated light can trigger neighbors; Electrical crosstalk can also correlate events.","failure":"若採用「同時多像素事件必然都是多個外來光子」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming coincidences always mean multiple incident photons\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「光學串擾」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「電性串擾也能造成相關事件」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Optical crosstalk, its observable and one remaining uncertainty. Explain how \"Electrical crosstalk can also correlate events\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-12-k1","title":"光學串擾／物理與模型","titleEn":"Optical crosstalk / Physics and model","text":"診斷機制：電性串擾也能造成相關事件。","textEn":"Diagnostic mechanism: Electrical crosstalk can also correlate events."},{"id":"a080-v8-12-k2","title":"光學串擾／驗證與限制","titleEn":"Optical crosstalk / Verification and limits","text":"可證偽性：「同時多像素事件必然都是多個外來光子」與「雪崩產生的光可能觸發鄰近像素」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming coincidences always mean multiple incident photons\" is not equivalent to \"Avalanche-generated light can trigger neighbors\"; the control must expose their difference."}],"quiz":{"question":"檢查「光學串擾」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Optical crosstalk?","options":["同時多像素事件必然都是多個外來光子","將低光強線性外推到任意高光強","電性串擾也能造成相關事件"],"optionsEn":["Assuming coincidences always mean multiple incident photons","Extending low-flux linearity to arbitrary flux","Electrical crosstalk can also correlate events"],"answer":2,"explanation":"電性串擾也能造成相關事件；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Electrical crosstalk can also correlate events. The competing claim omits a necessary condition or mechanism."}}]},{"id":"a080-stage03","order":3,"title":"死時間 → TDC 量化","titleEn":"Dead time to TDC quantization","description":"把「死時間」「時間抖動」「TDC 量化」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Dead time, Timing jitter, TDC quantization.","steps":[{"id":"a080-v8-13","order":1,"sequence":13,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-12"],"title":"死時間：建立模型","titleEn":"Dead time: construct and analyze","objective":"用可檢查的成果說明「計數率增加後量測可能偏離線性」。","objectiveEn":"Demonstrate the following with inspectable work: Measured count rate can become nonlinear.","instruction":"用假設固定死時間估算高計數壓縮，註明不可延長模型。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Estimate high-rate compression with a hypothetical nonparalyzable dead-time model. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"計數率增加後量測可能偏離線性；不同死時間模型有不同飽和曲線。","observationEn":"Measured count rate can become nonlinear; Dead-time models predict different saturation curves.","failure":"若採用「將低光強線性外推到任意高光強」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Extending low-flux linearity to arbitrary flux\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「死時間」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：計數率增加後量測可能偏離線性。","checkEn":"Submit the Dead time diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Measured count rate can become nonlinear.","knowledge":[{"id":"a080-v8-13-k1","title":"死時間／物理與模型","titleEn":"Dead time / Physics and model","text":"機制：計數率增加後量測可能偏離線性。","textEn":"Mechanism: Measured count rate can become nonlinear."},{"id":"a080-v8-13-k2","title":"死時間／驗證與限制","titleEn":"Dead time / Verification and limits","text":"模型邊界：不可由目前成果直接推出「將低光強線性外推到任意高光強」。","textEn":"Model boundary: the current result does not establish the following claim: Extending low-flux linearity to arbitrary flux."}],"quiz":{"question":"關於「死時間」，哪項推論有物理依據？","questionEn":"For Dead time, which inference has a physical basis?","options":["計數率增加後量測可能偏離線性","將低光強線性外推到任意高光強","將總脈寬全部歸因於半導體製程"],"optionsEn":["Measured count rate can become nonlinear","Extending low-flux linearity to arbitrary flux","Attributing total timing width to semiconductor processing"],"answer":0,"explanation":"計數率增加後量測可能偏離線性；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Measured count rate can become nonlinear. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-14","order":2,"sequence":14,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-13"],"title":"死時間：故障判讀與驗證","titleEn":"Dead time: diagnose and verify","objective":"以新增對照檢查「將低光強線性外推到任意高光強」這項錯誤主張。","objectiveEn":"Test the faulty claim: Extending low-flux linearity to arbitrary flux.","instruction":"接續前一步「死時間」成果，先指出錯誤主張「將低光強線性外推到任意高光強」漏掉哪個條件。新增診斷原理：不同死時間模型有不同飽和曲線。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Dead time artifact. Identify the missing condition in the faulty claim \"Extending low-flux linearity to arbitrary flux\". Introduce this diagnostic principle: Dead-time models predict different saturation curves. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"計數率增加後量測可能偏離線性；不同死時間模型有不同飽和曲線。","observationEn":"Measured count rate can become nonlinear; Dead-time models predict different saturation curves.","failure":"若採用「將低光強線性外推到任意高光強」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Extending low-flux linearity to arbitrary flux\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「死時間」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「不同死時間模型有不同飽和曲線」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Dead time, its observable and one remaining uncertainty. Explain how \"Dead-time models predict different saturation curves\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-14-k1","title":"死時間／物理與模型","titleEn":"Dead time / Physics and model","text":"診斷機制：不同死時間模型有不同飽和曲線。","textEn":"Diagnostic mechanism: Dead-time models predict different saturation curves."},{"id":"a080-v8-14-k2","title":"死時間／驗證與限制","titleEn":"Dead time / Verification and limits","text":"可證偽性：「將低光強線性外推到任意高光強」與「計數率增加後量測可能偏離線性」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Extending low-flux linearity to arbitrary flux\" is not equivalent to \"Measured count rate can become nonlinear\"; the control must expose their difference."}],"quiz":{"question":"檢查「死時間」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Dead time?","options":["將總脈寬全部歸因於半導體製程","不同死時間模型有不同飽和曲線","將低光強線性外推到任意高光強"],"optionsEn":["Attributing total timing width to semiconductor processing","Dead-time models predict different saturation curves","Extending low-flux linearity to arbitrary flux"],"answer":1,"explanation":"不同死時間模型有不同飽和曲線；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Dead-time models predict different saturation curves. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-15","order":3,"sequence":15,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-14"],"title":"時間抖動：建立模型","titleEn":"Timing jitter: construct and analyze","objective":"用可檢查的成果說明「系統抖動不完全等於 SPAD 本體抖動」。","objectiveEn":"Demonstrate the following with inspectable work: System jitter is not solely intrinsic SPAD jitter.","instruction":"畫到達時間直方圖並分拆雷射、偵測器與 TDC 貢獻。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Draw arrival histograms and separate laser, detector and TDC contributions. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"系統抖動不完全等於 SPAD 本體抖動；抖動各項平方相加需獨立假設。","observationEn":"System jitter is not solely intrinsic SPAD jitter; Quadrature jitter addition assumes independence.","failure":"若採用「將總脈寬全部歸因於半導體製程」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Attributing total timing width to semiconductor processing\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「時間抖動」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：系統抖動不完全等於 SPAD 本體抖動。","checkEn":"Submit the Timing jitter diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: System jitter is not solely intrinsic SPAD jitter.","knowledge":[{"id":"a080-v8-15-k1","title":"時間抖動／物理與模型","titleEn":"Timing jitter / Physics and model","text":"機制：系統抖動不完全等於 SPAD 本體抖動。","textEn":"Mechanism: System jitter is not solely intrinsic SPAD jitter."},{"id":"a080-v8-15-k2","title":"時間抖動／驗證與限制","titleEn":"Timing jitter / Verification and limits","text":"模型邊界：不可由目前成果直接推出「將總脈寬全部歸因於半導體製程」。","textEn":"Model boundary: the current result does not establish the following claim: Attributing total timing width to semiconductor processing."}],"quiz":{"question":"關於「時間抖動」，哪項推論有物理依據？","questionEn":"For Timing jitter, which inference has a physical basis?","options":["將總脈寬全部歸因於半導體製程","插值畫平滑曲線就代表新增時間解析度","系統抖動不完全等於 SPAD 本體抖動"],"optionsEn":["Attributing total timing width to semiconductor processing","Treating smooth interpolation as new time resolution","System jitter is not solely intrinsic SPAD jitter"],"answer":2,"explanation":"系統抖動不完全等於 SPAD 本體抖動；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"System jitter is not solely intrinsic SPAD jitter. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-16","order":4,"sequence":16,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-15"],"title":"時間抖動：故障判讀與驗證","titleEn":"Timing jitter: diagnose and verify","objective":"以新增對照檢查「將總脈寬全部歸因於半導體製程」這項錯誤主張。","objectiveEn":"Test the faulty claim: Attributing total timing width to semiconductor processing.","instruction":"接續前一步「時間抖動」成果，先指出錯誤主張「將總脈寬全部歸因於半導體製程」漏掉哪個條件。新增診斷原理：抖動各項平方相加需獨立假設。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Timing jitter artifact. Identify the missing condition in the faulty claim \"Attributing total timing width to semiconductor processing\". Introduce this diagnostic principle: Quadrature jitter addition assumes independence. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"系統抖動不完全等於 SPAD 本體抖動；抖動各項平方相加需獨立假設。","observationEn":"System jitter is not solely intrinsic SPAD jitter; Quadrature jitter addition assumes independence.","failure":"若採用「將總脈寬全部歸因於半導體製程」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Attributing total timing width to semiconductor processing\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「時間抖動」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「抖動各項平方相加需獨立假設」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Timing jitter, its observable and one remaining uncertainty. Explain how \"Quadrature jitter addition assumes independence\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-16-k1","title":"時間抖動／物理與模型","titleEn":"Timing jitter / Physics and model","text":"診斷機制：抖動各項平方相加需獨立假設。","textEn":"Diagnostic mechanism: Quadrature jitter addition assumes independence."},{"id":"a080-v8-16-k2","title":"時間抖動／驗證與限制","titleEn":"Timing jitter / Verification and limits","text":"可證偽性：「將總脈寬全部歸因於半導體製程」與「系統抖動不完全等於 SPAD 本體抖動」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Attributing total timing width to semiconductor processing\" is not equivalent to \"System jitter is not solely intrinsic SPAD jitter\"; the control must expose their difference."}],"quiz":{"question":"檢查「時間抖動」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Timing jitter?","options":["抖動各項平方相加需獨立假設","將總脈寬全部歸因於半導體製程","插值畫平滑曲線就代表新增時間解析度"],"optionsEn":["Quadrature jitter addition assumes independence","Attributing total timing width to semiconductor processing","Treating smooth interpolation as new time resolution"],"answer":0,"explanation":"抖動各項平方相加需獨立假設；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Quadrature jitter addition assumes independence. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-17","order":5,"sequence":17,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-16"],"title":"TDC 量化：建立模型","titleEn":"TDC quantization: construct and analyze","objective":"用可檢查的成果說明「分箱寬度限制可辨識的時間細節」。","objectiveEn":"Demonstrate the following with inspectable work: Bin width limits resolvable timing detail.","instruction":"以假設分箱大小比較同一事件序列的直方圖。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Bin the same hypothetical event sequence at two TDC resolutions. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"分箱寬度限制可辨識的時間細節；TDC 非均勻分箱需校正。","observationEn":"Bin width limits resolvable timing detail; Nonuniform TDC bins need calibration.","failure":"若採用「插值畫平滑曲線就代表新增時間解析度」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Treating smooth interpolation as new time resolution\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「TDC 量化」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：分箱寬度限制可辨識的時間細節。","checkEn":"Submit the TDC quantization diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Bin width limits resolvable timing detail.","knowledge":[{"id":"a080-v8-17-k1","title":"TDC 量化／物理與模型","titleEn":"TDC quantization / Physics and model","text":"機制：分箱寬度限制可辨識的時間細節。","textEn":"Mechanism: Bin width limits resolvable timing detail."},{"id":"a080-v8-17-k2","title":"TDC 量化／驗證與限制","titleEn":"TDC quantization / Verification and limits","text":"模型邊界：不可由目前成果直接推出「插值畫平滑曲線就代表新增時間解析度」。","textEn":"Model boundary: the current result does not establish the following claim: Treating smooth interpolation as new time resolution."}],"quiz":{"question":"關於「TDC 量化」，哪項推論有物理依據？","questionEn":"For TDC quantization, which inference has a physical basis?","options":["直接用 cΔt 作為單程距離","分箱寬度限制可辨識的時間細節","插值畫平滑曲線就代表新增時間解析度"],"optionsEn":["Using cΔt as one-way distance","Bin width limits resolvable timing detail","Treating smooth interpolation as new time resolution"],"answer":1,"explanation":"分箱寬度限制可辨識的時間細節；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Bin width limits resolvable timing detail. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-18","order":6,"sequence":18,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-17"],"title":"TDC 量化：故障判讀與驗證","titleEn":"TDC quantization: diagnose and verify","objective":"以新增對照檢查「插值畫平滑曲線就代表新增時間解析度」這項錯誤主張。","objectiveEn":"Test the faulty claim: Treating smooth interpolation as new time resolution.","instruction":"接續前一步「TDC 量化」成果，先指出錯誤主張「插值畫平滑曲線就代表新增時間解析度」漏掉哪個條件。新增診斷原理：TDC 非均勻分箱需校正。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding TDC quantization artifact. Identify the missing condition in the faulty claim \"Treating smooth interpolation as new time resolution\". Introduce this diagnostic principle: Nonuniform TDC bins need calibration. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"分箱寬度限制可辨識的時間細節；TDC 非均勻分箱需校正。","observationEn":"Bin width limits resolvable timing detail; Nonuniform TDC bins need calibration.","failure":"若採用「插值畫平滑曲線就代表新增時間解析度」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Treating smooth interpolation as new time resolution\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「TDC 量化」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「TDC 非均勻分箱需校正」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for TDC quantization, its observable and one remaining uncertainty. Explain how \"Nonuniform TDC bins need calibration\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-18-k1","title":"TDC 量化／物理與模型","titleEn":"TDC quantization / Physics and model","text":"診斷機制：TDC 非均勻分箱需校正。","textEn":"Diagnostic mechanism: Nonuniform TDC bins need calibration."},{"id":"a080-v8-18-k2","title":"TDC 量化／驗證與限制","titleEn":"TDC quantization / Verification and limits","text":"可證偽性：「插值畫平滑曲線就代表新增時間解析度」與「分箱寬度限制可辨識的時間細節」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Treating smooth interpolation as new time resolution\" is not equivalent to \"Bin width limits resolvable timing detail\"; the control must expose their difference."}],"quiz":{"question":"檢查「TDC 量化」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of TDC quantization?","options":["插值畫平滑曲線就代表新增時間解析度","直接用 cΔt 作為單程距離","TDC 非均勻分箱需校正"],"optionsEn":["Treating smooth interpolation as new time resolution","Using cΔt as one-way distance","Nonuniform TDC bins need calibration"],"answer":2,"explanation":"TDC 非均勻分箱需校正；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Nonuniform TDC bins need calibration. The competing claim omits a necessary condition or mechanism."}}]},{"id":"a080-stage04","order":4,"title":"直接飛行時間 → 熱點像素","titleEn":"Direct time of flight to Hot pixels","description":"把「直接飛行時間」「堆疊讀出」「熱點像素」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Direct time of flight, Stacked readout, Hot pixels.","steps":[{"id":"a080-v8-19","order":1,"sequence":19,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-18"],"title":"直接飛行時間：建立模型","titleEn":"Direct time of flight: construct and analyze","objective":"用可檢查的成果說明「往返飛行時間須除以二」。","objectiveEn":"Demonstrate the following with inspectable work: Round-trip flight time requires a factor of two.","instruction":"用 d=cΔt/2 算假設距離並扣除電子延遲。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。\n\n具體算例（全部數值為教學假設）：假設直接 ToF 系統已扣除電子延遲，測得往返時間 10 ns，取 c=3×10⁸ m/s，距離 d=ct/2=1.5 m。若時間誤差為 1 ns，對應距離誤差幅度 0.15 m。未處理多重路徑、光子統計及介質折射率；不可省略往返的二分之一。","instructionEn":"Compute hypothetical d=cΔt/2 after subtracting electronic delay. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.\n\nWorked example (all values are hypothetical teaching inputs): Assume a direct-ToF system has removed electronic delay and measures a 10 ns round trip. With c=3×10⁸ m/s, d=ct/2=1.5 m. A 1 ns timing-error magnitude corresponds to 0.15 m. Multipath, photon statistics and medium refractive index are excluded; the round-trip factor of one-half is essential.","observation":"往返飛行時間須除以二；多重反射會產生多個距離峰。","observationEn":"Round-trip flight time requires a factor of two; Multipath produces multiple range peaks.","failure":"若採用「直接用 cΔt 作為單程距離」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Using cΔt as one-way distance\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「直接飛行時間」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：往返飛行時間須除以二。\n算例驗收：驗算 1.5 m 與 0.15 m，畫出發射及返回兩段光路。","checkEn":"Submit the Direct time of flight diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Round-trip flight time requires a factor of two.\nWorked-example acceptance: Verify 1.5 m and 0.15 m and draw the outgoing and returning optical paths.","knowledge":[{"id":"a080-v8-19-k1","title":"直接飛行時間／物理與模型","titleEn":"Direct time of flight / Physics and model","text":"機制：往返飛行時間須除以二。","textEn":"Mechanism: Round-trip flight time requires a factor of two."},{"id":"a080-v8-19-k2","title":"直接飛行時間／驗證與限制","titleEn":"Direct time of flight / Verification and limits","text":"模型邊界：不可由目前成果直接推出「直接用 cΔt 作為單程距離」。\n假設數值與推算：假設直接 ToF 系統已扣除電子延遲，測得往返時間 10 ns，取 c=3×10⁸ m/s，距離 d=ct/2=1.5 m。若時間誤差為 1 ns，對應距離誤差幅度 0.15 m。未處理多重路徑、光子統計及介質折射率；不可省略往返的二分之一。","textEn":"Model boundary: the current result does not establish the following claim: Using cΔt as one-way distance.\nHypothetical inputs and calculation: Assume a direct-ToF system has removed electronic delay and measures a 10 ns round trip. With c=3×10⁸ m/s, d=ct/2=1.5 m. A 1 ns timing-error magnitude corresponds to 0.15 m. Multipath, photon statistics and medium refractive index are excluded; the round-trip factor of one-half is essential."}],"quiz":{"question":"關於「直接飛行時間」，哪項推論有物理依據？","questionEn":"For Direct time of flight, which inference has a physical basis?","options":["往返飛行時間須除以二","直接用 cΔt 作為單程距離","偵測器變多即保證事件資料全部送出"],"optionsEn":["Round-trip flight time requires a factor of two","Using cΔt as one-way distance","Assuming more pixels guarantee all events can be exported"],"answer":0,"explanation":"往返飛行時間須除以二；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Round-trip flight time requires a factor of two. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-20","order":2,"sequence":20,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-19"],"title":"直接飛行時間：故障判讀與驗證","titleEn":"Direct time of flight: diagnose and verify","objective":"以新增對照檢查「直接用 cΔt 作為單程距離」這項錯誤主張。","objectiveEn":"Test the faulty claim: Using cΔt as one-way distance.","instruction":"接續前一步「直接飛行時間」成果，先指出錯誤主張「直接用 cΔt 作為單程距離」漏掉哪個條件。新增診斷原理：多重反射會產生多個距離峰。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Direct time of flight artifact. Identify the missing condition in the faulty claim \"Using cΔt as one-way distance\". Introduce this diagnostic principle: Multipath produces multiple range peaks. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"往返飛行時間須除以二；多重反射會產生多個距離峰。","observationEn":"Round-trip flight time requires a factor of two; Multipath produces multiple range peaks.","failure":"若採用「直接用 cΔt 作為單程距離」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Using cΔt as one-way distance\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「直接飛行時間」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「多重反射會產生多個距離峰」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Direct time of flight, its observable and one remaining uncertainty. Explain how \"Multipath produces multiple range peaks\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-20-k1","title":"直接飛行時間／物理與模型","titleEn":"Direct time of flight / Physics and model","text":"診斷機制：多重反射會產生多個距離峰。","textEn":"Diagnostic mechanism: Multipath produces multiple range peaks."},{"id":"a080-v8-20-k2","title":"直接飛行時間／驗證與限制","titleEn":"Direct time of flight / Verification and limits","text":"可證偽性：「直接用 cΔt 作為單程距離」與「往返飛行時間須除以二」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Using cΔt as one-way distance\" is not equivalent to \"Round-trip flight time requires a factor of two\"; the control must expose their difference."}],"quiz":{"question":"檢查「直接飛行時間」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Direct time of flight?","options":["偵測器變多即保證事件資料全部送出","多重反射會產生多個距離峰","直接用 cΔt 作為單程距離"],"optionsEn":["Assuming more pixels guarantee all events can be exported","Multipath produces multiple range peaks","Using cΔt as one-way distance"],"answer":1,"explanation":"多重反射會產生多個距離峰；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Multipath produces multiple range peaks. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-21","order":3,"sequence":21,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-20"],"title":"堆疊讀出：建立模型","titleEn":"Stacked readout: construct and analyze","objective":"用可檢查的成果說明「堆疊可改善面積配置但不消除讀出瓶頸」。","objectiveEn":"Demonstrate the following with inspectable work: Stacking improves area allocation but not every readout bottleneck.","instruction":"畫 SPAD 層、計數器層及連接，檢查填充率和資料吞吐。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Draw detector/counter tiers and links and check fill factor and throughput. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"堆疊可改善面積配置但不消除讀出瓶頸；資料遺失會偏差時間直方圖。","observationEn":"Stacking improves area allocation but not every readout bottleneck; Dropped data can bias time histograms.","failure":"若採用「偵測器變多即保證事件資料全部送出」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming more pixels guarantee all events can be exported\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「堆疊讀出」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：堆疊可改善面積配置但不消除讀出瓶頸。","checkEn":"Submit the Stacked readout diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Stacking improves area allocation but not every readout bottleneck.","knowledge":[{"id":"a080-v8-21-k1","title":"堆疊讀出／物理與模型","titleEn":"Stacked readout / Physics and model","text":"機制：堆疊可改善面積配置但不消除讀出瓶頸。","textEn":"Mechanism: Stacking improves area allocation but not every readout bottleneck."},{"id":"a080-v8-21-k2","title":"堆疊讀出／驗證與限制","titleEn":"Stacked readout / Verification and limits","text":"模型邊界：不可由目前成果直接推出「偵測器變多即保證事件資料全部送出」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming more pixels guarantee all events can be exported."}],"quiz":{"question":"關於「堆疊讀出」，哪項推論有物理依據？","questionEn":"For Stacked readout, which inference has a physical basis?","options":["偵測器變多即保證事件資料全部送出","只報遮罩後最佳暗計數而不報失去像素","堆疊可改善面積配置但不消除讀出瓶頸"],"optionsEn":["Assuming more pixels guarantee all events can be exported","Reporting improved dark rate without lost pixels","Stacking improves area allocation but not every readout bottleneck"],"answer":2,"explanation":"堆疊可改善面積配置但不消除讀出瓶頸；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Stacking improves area allocation but not every readout bottleneck. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-22","order":4,"sequence":22,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-21"],"title":"堆疊讀出：故障判讀與驗證","titleEn":"Stacked readout: diagnose and verify","objective":"以新增對照檢查「偵測器變多即保證事件資料全部送出」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming more pixels guarantee all events can be exported.","instruction":"接續前一步「堆疊讀出」成果，先指出錯誤主張「偵測器變多即保證事件資料全部送出」漏掉哪個條件。新增診斷原理：資料遺失會偏差時間直方圖。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Stacked readout artifact. Identify the missing condition in the faulty claim \"Assuming more pixels guarantee all events can be exported\". Introduce this diagnostic principle: Dropped data can bias time histograms. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"堆疊可改善面積配置但不消除讀出瓶頸；資料遺失會偏差時間直方圖。","observationEn":"Stacking improves area allocation but not every readout bottleneck; Dropped data can bias time histograms.","failure":"若採用「偵測器變多即保證事件資料全部送出」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming more pixels guarantee all events can be exported\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「堆疊讀出」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「資料遺失會偏差時間直方圖」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Stacked readout, its observable and one remaining uncertainty. Explain how \"Dropped data can bias time histograms\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-22-k1","title":"堆疊讀出／物理與模型","titleEn":"Stacked readout / Physics and model","text":"診斷機制：資料遺失會偏差時間直方圖。","textEn":"Diagnostic mechanism: Dropped data can bias time histograms."},{"id":"a080-v8-22-k2","title":"堆疊讀出／驗證與限制","titleEn":"Stacked readout / Verification and limits","text":"可證偽性：「偵測器變多即保證事件資料全部送出」與「堆疊可改善面積配置但不消除讀出瓶頸」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming more pixels guarantee all events can be exported\" is not equivalent to \"Stacking improves area allocation but not every readout bottleneck\"; the control must expose their difference."}],"quiz":{"question":"檢查「堆疊讀出」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Stacked readout?","options":["資料遺失會偏差時間直方圖","偵測器變多即保證事件資料全部送出","只報遮罩後最佳暗計數而不報失去像素"],"optionsEn":["Dropped data can bias time histograms","Assuming more pixels guarantee all events can be exported","Reporting improved dark rate without lost pixels"],"answer":0,"explanation":"資料遺失會偏差時間直方圖；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Dropped data can bias time histograms. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-23","order":5,"sequence":23,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-22"],"title":"熱點像素：建立模型","titleEn":"Hot pixels: construct and analyze","objective":"用可檢查的成果說明「移除高暗計數像素也減少有效取樣」。","objectiveEn":"Demonstrate the following with inspectable work: Masking high-dark pixels reduces effective sampling.","instruction":"制定遮罩前後影像與偵測率比較，保留被移除面積。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Compare images/detection before and after masking and retain excluded area. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"移除高暗計數像素也減少有效取樣；遮罩版本應與影像同步保存。","observationEn":"Masking high-dark pixels reduces effective sampling; Mask versions should accompany image records.","failure":"若採用「只報遮罩後最佳暗計數而不報失去像素」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Reporting improved dark rate without lost pixels\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「熱點像素」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：移除高暗計數像素也減少有效取樣。","checkEn":"Submit the Hot pixels diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Masking high-dark pixels reduces effective sampling.","knowledge":[{"id":"a080-v8-23-k1","title":"熱點像素／物理與模型","titleEn":"Hot pixels / Physics and model","text":"機制：移除高暗計數像素也減少有效取樣。","textEn":"Mechanism: Masking high-dark pixels reduces effective sampling."},{"id":"a080-v8-23-k2","title":"熱點像素／驗證與限制","titleEn":"Hot pixels / Verification and limits","text":"模型邊界：不可由目前成果直接推出「只報遮罩後最佳暗計數而不報失去像素」。","textEn":"Model boundary: the current result does not establish the following claim: Reporting improved dark rate without lost pixels."}],"quiz":{"question":"關於「熱點像素」，哪項推論有物理依據？","questionEn":"For Hot pixels, which inference has a physical basis?","options":["用單一雪崩脈衝高度精確判斷入射光子數","移除高暗計數像素也減少有效取樣","只報遮罩後最佳暗計數而不報失去像素"],"optionsEn":["Inferring exact photon number from one avalanche height","Masking high-dark pixels reduces effective sampling","Reporting improved dark rate without lost pixels"],"answer":1,"explanation":"移除高暗計數像素也減少有效取樣；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Masking high-dark pixels reduces effective sampling. The competing claim omits a necessary condition or mechanism."}},{"id":"a080-v8-24","order":6,"sequence":24,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-spad","v8-c-sipm","v8-c-tof"],"prerequisiteIds":["a080-v8-23"],"title":"熱點像素：故障判讀與驗證","titleEn":"Hot pixels: diagnose and verify","objective":"以新增對照檢查「只報遮罩後最佳暗計數而不報失去像素」這項錯誤主張。","objectiveEn":"Test the faulty claim: Reporting improved dark rate without lost pixels.","instruction":"接續前一步「熱點像素」成果，先指出錯誤主張「只報遮罩後最佳暗計數而不報失去像素」漏掉哪個條件。新增診斷原理：遮罩版本應與影像同步保存。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Hot pixels artifact. Identify the missing condition in the faulty claim \"Reporting improved dark rate without lost pixels\". Introduce this diagnostic principle: Mask versions should accompany image records. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"移除高暗計數像素也減少有效取樣；遮罩版本應與影像同步保存。","observationEn":"Masking high-dark pixels reduces effective sampling; Mask versions should accompany image records.","failure":"若採用「只報遮罩後最佳暗計數而不報失去像素」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Reporting improved dark rate without lost pixels\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「熱點像素」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「遮罩版本應與影像同步保存」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Hot pixels, its observable and one remaining uncertainty. Explain how \"Mask versions should accompany image records\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a080-v8-24-k1","title":"熱點像素／物理與模型","titleEn":"Hot pixels / Physics and model","text":"診斷機制：遮罩版本應與影像同步保存。","textEn":"Diagnostic mechanism: Mask versions should accompany image records."},{"id":"a080-v8-24-k2","title":"熱點像素／驗證與限制","titleEn":"Hot pixels / Verification and limits","text":"可證偽性：「只報遮罩後最佳暗計數而不報失去像素」與「移除高暗計數像素也減少有效取樣」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Reporting improved dark rate without lost pixels\" is not equivalent to \"Masking high-dark pixels reduces effective sampling\"; the control must expose their difference."}],"quiz":{"question":"檢查「熱點像素」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Hot pixels?","options":["只報遮罩後最佳暗計數而不報失去像素","用單一雪崩脈衝高度精確判斷入射光子數","遮罩版本應與影像同步保存"],"optionsEn":["Reporting improved dark rate without lost pixels","Inferring exact photon number from one avalanche height","Mask versions should accompany image records"],"answer":2,"explanation":"遮罩版本應與影像同步保存；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Mask versions should accompany image records. The competing claim omits a necessary condition or mechanism."}}]}],"subcategory":"sensors","subcategoryTitle":"影像與光子感測","subcategoryTitleEn":"Image and photon sensors"}};
